import matlab.net.http.*
req = RequestMessage("GET");
resp = send(req, "https://httpbin.org/json");
if resp.StatusCode == StatusCode.OK
    data = resp.Body.Data;       % JSON auto-decoded to struct
end

import matlab.net.http.*
body = MessageBody(struct("name", "sensor1", "value", 3.2));
req = RequestMessage("POST", [], body);
resp = send(req, "https://httpbin.org/post");

import matlab.net.http.*
hdr = [HeaderField("Accept", "application/json"), ...
       HeaderField("X-Api-Key", getenv("MY_API_KEY"))];
resp = send(RequestMessage("GET", hdr), "https://api.example.com/v1/items");

import matlab.net.http.*
ct = field.ContentTypeField("text/plain");
req = RequestMessage("PUT", ct, MessageBody("hello"));

import matlab.net.http.*
token = getenv("API_TOKEN");
auth = field.AuthorizationField("Authorization", "Bearer " + token);
resp = send(RequestMessage("GET", auth), "https://api.example.com/me");

import matlab.net.http.*
req = RequestMessage(RequestMethod.DELETE);
resp = send(req, "https://httpbin.org/delete");
resp.StatusCode

import matlab.net.http.*
resp = send(RequestMessage("GET"), "https://httpbin.org/status/404");
if getClass(resp.StatusCode) ~= StatusClass.Successful
    warning("HTTP %d %s", double(resp.StatusCode), getReasonPhrase(resp.StatusCode));
end

import matlab.net.http.*
